  "schema_version": "scientist-design-v1",
  "scenario": "two people bargaining over a mug",
  "agents": [
    {
      "name": "Alice",
      "role": "seller",
      "goal": "maximize profit from the sale",
      "constraints": ["must accept a price above $5"]
    },
    {
      "name": "Bob",
      "role": "buyer",
      "goal": "minimize cost of the mug",
      "constraints": ["must offer at least $3"]
    }
  ],
  "outcome": {
    "name": "final price",
    "operationalization": "the price agreed upon by Alice and Bob",
    "measurement_question": "What is the final price agreed upon by the two agents?",
    "respondent": "both agents"
  },
  "causes": [
    {
      "name": "initial offer",
      "hypothesis": "A higher initial offer by Alice leads to a higher final price",
      "predicted_direction": "increase",
      "treatment_values": ["$8", "$10", "$12"]
    },
    {
      "name": "counteroffer",
      "hypothesis": "A lower counteroffer by Bob leads to a lower final price",
      "predicted_direction": "decrease",
      "treatment_values": ["$4", "$5", "$6"]
    },
    {
      "name": "mug quality",
      "hypothesis": "Higher mug quality leads to a higher final price",
      "predicted_direction": "increase",
      "treatment_values": ["high", "medium", "low"]
    }
  ],
  "information_scope": {
    "public": ["mug quality"],
    "private": [
      {
        "agent": "Alice",
        "information": ["initial offer", "mug quality"]
      },
      {
        "agent": "Bob",
        "information": ["counteroffer", "mug quality"]
      }
    ]
  },
  "interaction": {
    "order": ["Alice", "Bob"],
    "max_turns": 2,
    "stopping_rule": "when both agents agree on a price"
  }
}

