  "scenario": "a judge is setting bail for a criminal defendant who committed 50,000 dollars in tax fraud",
  "agents": [
    {
      "name": "Judge",
      "role": "Legal authority responsible for determining bail",
      "goal": "Set bail in a manner that balances defendant's right to freedom with public safety",
      "constraints": ["Must follow legal guidelines", "Cannot consider unrelated factors", "Must account for flight risk"]
    },
    {
      "name": "Defense Attorney",
      "role": "Legal representative of the defendant",
      "goal": "Advocate for the defendant's release on bail",
      "constraints": ["Cannot make false claims", "Must present evidence", "Cannot disclose confidential information"]
    },
    {
      "name": "Prosecutor",
      "role": "Legal representative of the state",
      "goal": "Ensure defendant remains in custody to prevent flight",
      "constraints": ["Cannot present irrelevant evidence", "Must follow legal procedures", "Cannot threaten the defendant"]
    }
  ],
  "outcome": {
    "name": "Bail amount",
    "operationalization": "The monetary amount set by the judge as bail",
    "measurement_question": "What is the exact bail amount determined by the judge?",
    "respondent": "Judge"
  },
  "causes": [
    {
      "name": "Flight risk",
      "hypothesis": "Higher flight risk leads to higher bail",
      "predicted_direction": "increase",
      "treatment_values": ["Low", "Medium", "High"]
    },
    {
      "name": "Asset forfeiture",
      "hypothesis": "Presence of assets leads to lower bail",
      "predicted_direction": "decrease",
      "treatment_values": ["No assets", "Some assets", "Significant assets"]
    },
    {
      "name": "Prior criminal record",
      "hypothesis": "More prior convictions lead to higher bail",
      "predicted_direction": "increase",
      "treatment_values": ["No prior record", "One prior conviction", "Multiple prior convictions"]
    }
  ],
  "information_scope": {
    "public": ["Tax fraud amount", "Charge severity", "Legal statutes"],
    "private": [
      {
        "agent": "Defense Attorney",
        "information": ["Defendant's financial status", "Witness testimony", "Evidence of intent"]
      },
      {
        "agent": "Prosecutor",
        "information": ["Evidence of flight risk", "Prior criminal record details", "Asset location"]
      }
    ]
  },
  "interaction": {
    "order": ["Judge", "Defense Attorney", "Prosecutor"],
    "max_turns": 3,
    "stopping_rule": "Judge makes final bail decision after considering all inputs"
  }
}

