{
  "schema_version": "scientist-design-v1",
  "scenario": "3 bidders participating in an auction for a piece of art starting at fifty dollars",
  "agents": [
    {
      "name": "Agent A",
      "role": "Conservative bidder",
      "goal": "Maximize profit while minimizing risk",
      "constraints": ["Bids only when confident about value"]
    },
    {
      "name": "Agent B",
      "role": "Speculative bidder",
      "goal": "Achieve maximum return on investment",
      "constraints": ["Bids aggressively when others show interest"]
    },
    {
      "name": "Agent C",
      "role": "Passive observer",
      "goal": "Observe bidding patterns without participating",
      "constraints": ["Only bids if others have already bid"]
    }
  ],
  "outcome": {
    "name": "Final auction price",
    "operationalization": "The highest bid accepted by the auctioneer",
    "measurement_question": "What is the final price of the art piece after the auction?",
    "respondent": "Auctioneer"
  },
  "causes": [
    {
      "name": "Bidding strategy",
      "hypothesis": "Aggressive bidding increases final price",
      "predicted_direction": "increase",
      "treatment_values": ["Aggressive", "Conservative", "Passive"]
    },
    {
      "name": "Starting price",
      "hypothesis": "Higher starting price leads to higher final price",
      "predicted_direction": "increase",
      "treatment_values": ["$50", "$100", "$150"]
    },
    {
      "name": "Bidder experience",
      "hypothesis": "Experienced bidders drive up final price",
      "predicted_direction": "increase",
      "treatment_values": ["Novice", "Intermediate", "Expert"]
    }
  ],
  "information_scope": {
    "public": ["Current bid", "Starting price", "Number of bidders"],
    "private": [
      {
        "agent": "Agent A",
        "information": ["Estimated value of art", "Risk tolerance"]
      },
      {
        "agent": "Agent B",
        "information": ["Market research data", "Financial capacity"]
      },
      {
        "agent": "Agent C",
        "information": ["Bidding history", "Personal budget"]
      }
    ]
  },
  "interaction": {
    "order": ["Agent A", "Agent B", "Agent C"],
    "max_turns": 3,
    "stopping_rule": "Auction ends when no more bids are placed"
  }
}

